import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback } from 'react'
import { useApplicationContextValue } from '../../context'
import { getTotalCollections, getCollectionDetails, uploadCollecion, downloadCollection, clearRecords } from '../actions'

export const useApplicationServiceCall = (actionsCall = () => {}) => {
  const [applicationState, dispatch] = useApplicationContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const request = useCallback(async (payload = {}) => {
    await callApi(actionsCall({
      ...payload
    }))
  }, [callApi, actionsCall])

  // application store
  // request method
  return [applicationState, request]
}

export const useCollectionListData = () => {
  return useApplicationServiceCall(getTotalCollections)
}

export const useCollectionDetails = () => {
  return useApplicationServiceCall(getCollectionDetails)
}

export const useImportCollectionData = () => {
  return useApplicationServiceCall(uploadCollecion)
}

export const useExportCollectionData = () => {
  return useApplicationServiceCall(downloadCollection)
}

export const useClearRecords = () => {
  return useApplicationServiceCall(clearRecords)
}
