import { useCallback, useEffect, useRef, useState } from 'react'
import { Row, Button, Pagination } from 'antd'
import ReactJson from 'react-json-view'
import { PageNumberContainer, DetailsWrapper } from './index.style'
import { showNotification } from '../../../../../../components/ShowNotification'
import { useLoaderContextValue, useErrorContextValue, resetError } from '@pasarpolis/common-react-hooks'
import {
  useCollectionDetails,
  useClearRecords
} from '../../../state/hook/useApplicationState'
import CircularLoader from '../../../../../../components/CircularLoader'

function MappingCollectionData (props) {
  const [state, setState] = useState({
    objConverter: {},
    limit: 10,
    offset: 0,
    totalRecords: 0,
    dataList: []
  })
  const that = useRef({
    isLoadCalled: false
  })

  const [{ COLLECTION_DETAIL_LOADER }] = useLoaderContextValue()

  const isLoaderActive = (COLLECTION_DETAIL_LOADER)

  const [pageState, getCollectionDetailRequest] = useCollectionDetails()

  const [{
    collectionDetailStatus,
    clearRecordsStatus
  }, dispatchError] = useErrorContextValue()
  const [clearRecordsState] = useClearRecords()

  const loadData = useCallback((offset = 0) => {
    if (!COLLECTION_DETAIL_LOADER) {
      const collection = props.match.params.collection
      getCollectionDetailRequest(
        {
          query: {
            collection,
            offset: offset,
            limit: state.limit

          }
        }
      )
    }
  }, [getCollectionDetailRequest, props, state, COLLECTION_DETAIL_LOADER])

  useEffect(() => {
    if (!that.current.isLoadCalled) {
      that.current.isLoadCalled = true
      loadData()
    }
  }, [loadData])

  useEffect(() => {
    if (collectionDetailStatus === 'success') {
      setState((prevState) => ({
        ...prevState,
        objConverter: pageState.collectionDetailData,
        dataList: pageState.collectionDetailData.data,
        totalRecords: pageState.collectionDetailData.meta_data.total_records
      }))
      dispatchError(resetError({
        collectionDetailStatus: undefined
      }))
    }
  }, [collectionDetailStatus, pageState, dispatchError])

  useEffect(() => {
    if (clearRecordsStatus === 'success') {
      const values = clearRecordsState.clearRecordsData.records_cleared + ' records cleared'
      showNotification('success', values)
      dispatchError(resetError({
        clearRecordsStatus: undefined
      }))
      setTimeout(() => {
        props.history.replace('/data-collections')
      }, 1000)
    } else if (clearRecordsStatus) {
      showNotification('error', 'Try after some time...!')
      dispatchError(resetError({
        clearRecordsStatus: undefined
      }))
    }
  }, [clearRecordsStatus, clearRecordsState, props, dispatchError])

  const handlePageChange = (pageNumber) => {
    setState((prevState) => ({
      ...prevState,
      offset: pageNumber - 1
    }))
    loadData(pageNumber - 1)
  }

  const handleGoBack = useCallback(() => {
    props.history.goBack()
  }, [props.history])

  return (
    <CircularLoader isSpining={isLoaderActive}>
      <DetailsWrapper>
        <Row className='row'>
          <Button type='primary' onClick={handleGoBack}>
            Back
          </Button>
          {/* <PermissionCheckerV2 requiredPermission='ops.clear_collections'>
            <Button type='primary' onClick={handleSubmit}>
              Clear Data
            </Button>
          </PermissionCheckerV2> */}

          <PageNumberContainer>
            <Pagination
              current={state.offset + 1}
              total={state.totalRecords}
              defaultPageSize={10}
              onChange={handlePageChange}
            />
          </PageNumberContainer>
        </Row>
        <div className='table'>
          {
            state.dataList.map(
              (value, qindex) =>
                <ReactJson
                  key={qindex}
                  name='data'
                  src={value}
                  displayDataTypes={false}
                  displayObjectSize={false}
                  enableClipboard={false}
                />
            )
          }
        </div>
      </DetailsWrapper>
    </CircularLoader>
  )
}

export default MappingCollectionData
